import org.mockito.Mockito.*
import static org.hamcrest.MatcherAssert.assertThat;
import static org.hamcrest.Matchers.*;
import java.io.ByteArrayOutputStream;
import java.io.UnsupportedEncodingException;
import java.util.BitSet;
import org.apache.commons.codec.BinaryDecoder;
import org.apache.commons.codec.BinaryEncoder;
import org.apache.commons.codec.CharEncoding;
import org.apache.commons.codec.DecoderException;
import org.apache.commons.codec.EncoderException;
import org.apache.commons.codec.StringDecoder;
import org.apache.commons.codec.StringEncoder;
import org.apache.commons.codec.binary.StringUtils;

public class QuotedPrintableCodecTest{
private QuotedPrintableCodec quotedPrintableCodec;

    @Before
    public void setUp() throws Exception {
        quotedPrintableCodec = new QuotedPrintableCodec();
    }

    @After
    public void tearDown() throws Exception {
        quotedPrintableCodec = null;
    }

    @Test
    public void testDecodeQuotedPrintable_Null() throws Exception {
        Assert.assertNull(QuotedPrintableCodec.decodeQuotedPrintable(null));
    }

    @Test
    public void testDecodeQuotedPrintable_Normal() throws Exception {
        byte[] bytes = "Hello World!".getBytes(CharEncoding.UTF_8);
        byte[] result = QuotedPrintableCodec.decodeQuotedPrintable(bytes);
        Assert.assertArrayEquals(bytes, result);
    }

    @Test
    public void testDecodeQuotedPrintable_Escape() throws Exception {
        byte[] bytes = "=48=65=6c=6c=6f=20=57=6f=72=6c=64%21".getBytes(CharEncoding.UTF_8);
        byte[] result = QuotedPrintableCodec.decodeQuotedPrintable(bytes);
        Assert.assertArrayEquals("Hello World!".getBytes(CharEncoding.UTF_8), result);
    }

    @Test(expected = DecoderException.class)
    public void testDecodeQuotedPrintable_Invalid() throws Exception {
        byte[] bytes = "=48=65=6c=6c=6f=20=57=6f=72=6c=64".getBytes(CharEncoding.UTF_8);
        QuotedPrintableCodec.decodeQuotedPrintable(bytes);
    }

    @Test
    public void testDecodeQuotedPrintable_LineBreak() throws Exception {
        byte[] bytes = "Hello=0D=0AWorld!".getBytes(CharEncoding.UTF_8);
        byte[] result = QuotedPrintableCodec.decodeQuotedPrintable(bytes);
        Assert.assertArrayEquals("Hello\r\nWorld!".getBytes(CharEncoding.UTF_8), result);
    }

    @Test
    public void testEncodeQuotedPrintable() throws Exception {
        byte[] bytes = "Hello World!".getBytes(CharEncoding.UTF_8);
        byte[] result = quotedPrintableCodec.encode(bytes);
        Assert.assertNotNull(result);
    }

    @Test
    public void testEncodeQuotedPrintable_LineBreak() throws Exception {
        byte[] bytes = "Hello\r\nWorld!".getBytes(CharEncoding.UTF_8);
        byte[] result = quotedPrintableCodec.encode(bytes);
        Assert.assertNotNull(result);
    }

    @Test
    public void testDecode() throws Exception {
        String str = "Hello World!";
        byte[] bytes = quotedPrintableCodec.encode(str.getBytes(CharEncoding.UTF_8));
        byte[] result = quotedPrintableCodec.decode(bytes);
        Assert.assertArrayEquals(str.getBytes(CharEncoding.UTF_8), result);
    }

    @Test
    public void testDecode_String() throws Exception {
        String str = "Hello World!";
        byte[] bytes = quotedPrintableCodec.encode(str.getBytes(CharEncoding.UTF_8));
        String result = quotedPrintableCodec.decode(bytes, CharEncoding.UTF_8);
        Assert.assertEquals(str, result);
    }

    @Test
    public void testEncode() throws Exception {
        String str = "Hello World!";
        byte[] result = quotedPrintableCodec.encode(str);
        Assert.assertNotNull(result);
    }

    @Test
    public void testGetDefaultCharset() throws Exception {
        Assert.assertEquals(CharEncoding.UTF_8, quotedPrintableCodec.getDefaultCharset());
    }
} 
